ga1l(){return"\u0905\u0928\u0941\u092e\u094b\u0926\u093f\u0924 \u0938\u0939\u093e\u092f\u0915"},
gBL(){return"\u0938\u093e\u092e\u093e\u0928\u094d\u092f \u0915\u0930\u094d\u092e\u091a\u093e\u0930\u0940"},
ga18(){return"\u0915\u094b\u0908 \u0915\u094d\u0932\u093f\u0928\u093f\u0915\u0932 \u092a\u0939\u0941\u0902\u091a \u0928\u0939\u0940\u0902: \u091a\u093f\u0915\u093f\u0924\u094d\u0938\u093e \u0907\u0924\u093f\u0939\u093e\u0938, \u0905\u0938\u094d\u092a\u0924\u093e\u0932 \u092f\u093e \u0921\u093e\u092f\u0930\u0940 \u0928\u0939\u0940\u0902 \u0926\u0947\u0916 \u0938\u0915\u0924\u093e\u0964"},
gGQ(){return"\u092a\u0936\u0941 \u091a\u093f\u0915\u093f\u0924\u094d\u0938\u093e \u0938\u0939\u093e\u092f\u0915"},
gVt(){return"\u0907\u0924\u093f\u0939\u093e\u0938 \u0926\u0947\u0916 \u0938\u0915\u0924\u093e \u0939\u0948 \u0914\u0930 \u092a\u0936\u0941 \u091a\u093f\u0915\u093f\u0924\u094d\u0938\u0915 \u0915\u0940 \u0938\u094d\u0935\u0940\u0915\u0943\u0924\u093f \u0915\u0947 \u0924\u0939\u0924 \u092c\u0928\u093e \u0938\u0915\u0924\u093e \u0939\u0948"},
gC8(){return"\u092a\u094d\u0930\u0915\u094d\u0930\u093f\u092f\u093e \u092e\u0947\u0902"},
gK9(){return"\u092e\u0948\u0928\u0941\u0905\u0932 \u0938\u092e\u0940\u0915\u094d\u0937\u093e"},
gLU(){return"\u092e\u0948\u0928\u0941\u0905\u0932 \u0938\u0924\u094d\u092f\u093e\u092a\u0928 \u0915\u093e \u0905\u0928\u0941\u0930\u094b\u0927 \u0915\u0930\u0947\u0902"},
gagO(){return"\u0938\u0924\u094d\u092f\u093e\u092a\u093f\u0924 \xb7 \u092d\u0942\u092e\u093f\u0915\u093e \u0932\u0949\u0915"},
gPm(){return"\u091b\u093e\u0924\u094d\u0930 \u0938\u0924\u094d\u092f\u093e\u092a\u093f\u0924\u0964"},
gahp(){return"\u092a\u0936\u0941 \u091a\u093f\u0915\u093f\u0924\u094d\u0938\u0915 \u0938\u0924\u094d\u092f\u093e\u092a\u093f\u0924\u0964"},
gPg(){return"\u0926\u0938\u094d\u0924\u093e\u0935\u0947\u091c\u093c \u092a\u094d\u0930\u093e\u092a\u094d\u0924 \u0939\u0941\u0906\u0964 \u0938\u094d\u0935\u091a\u093e\u0932\u093f\u0924 OCR \u0938\u0924\u094d\u092f\u093e\u092a\u0928 \u092a\u094d\u0930\u0915\u094d\u0930\u093f\u092f\u093e \u092e\u0947\u0902 \u0939\u0948; \u092a\u0942\u0930\u093e \u0939\u094b\u0928\u0947 \u092a\u0930 \u0938\u094d\u0925\u093f\u0924\u093f \u0905\u092a\u0921\u0947\u091f \u0939\u094b\u0917\u0940\u0964"},
gahk(){return"\u0926\u0938\u094d\u0924\u093e\u0935\u0947\u091c\u093c \u092a\u094d\u0930\u093e\u092a\u094d\u0924 \u0939\u0941\u090f\u0964 \u0932\u093e\u0907\u0938\u0947\u0902\u0938 \u0914\u0930 \u092d\u094c\u0924\u093f\u0915 \u0926\u0938\u094d\u0924\u093e\u0935\u0947\u091c\u093c \u0915\u093e \u0938\u0924\u094d\u092f\u093e\u092a\u0928 \u092a\u094d\u0930\u0915\u094d\u0930\u093f\u092f\u093e \u092e\u0947\u0902 \u0939\u0948; \u092a\u0942\u0930\u093e \u0939\u094b\u0928\u0947 \u092a\u0930 \u0938\u094d\u0925\u093f\u0924\u093f \u0905\u092a\u0921\u0947\u091f \u0939\u094b\u0917\u0940\u0964"},
gGP(){return"\u0938\u094d\u0935\u091a\u093e\u0932\u093f\u0924 \u0938\u0924\u094d\u092f\u093e\u092a\u0928 \u0928\u0947 \u0907\u0938 \u092a\u094d\u0930\u094b\u092b\u093c\u093e\u0907\u0932 \u0915\u094b \u092e\u0902\u091c\u093c\u0942\u0930\u0940 \u0928\u0939\u0940\u0902 \u0926\u0940\u0964 RedVet \u092d\u0947\u091c\u0947 \u0917\u090f \u0921\u0947\u091f\u093e \u0915\u0940 \u0938\u092e\u0940\u0915\u094d\u0937\u093e \u0915\u0930\u0947\u0917\u093e\u0964"},
gagC(){return"\u0905\u092a\u0928\u093e \u091b\u093e\u0924\u094d\u0930 \u0915\u093e\u0930\u094d\u0921 \u0905\u092a\u0932\u094b\u0921 \u0915\u0930\u0947\u0902"},
gagD(){return"\u0905\u092a\u0928\u093e \u092a\u0936\u0941 \u091a\u093f\u0915\u093f\u0924\u094d\u0938\u0915 \u0932\u093e\u0907\u0938\u0947\u0902\u0938 \u092f\u093e \u0921\u093f\u0917\u094d\u0930\u0940 \u0905\u092a\u0932\u094b\u0921 \u0915\u0930\u0947\u0902 \u091c\u094b \u0906\u092a\u0915\u094b \u092a\u0936\u0941 \u091a\u093f\u0915\u093f\u0924\u094d\u0938\u0915 \u0915\u0947 \u0930\u0942\u092a \u092e\u0947\u0902 \u092a\u094d\u0930\u092e\u093e\u0923\u093f\u0924 \u0915\u0930\u0947\u0964 \u0935\u094d\u092f\u0915\u094d\u0924\u093f\u0917\u0924 \u092a\u0939\u091a\u093e\u0928 \u092a\u0924\u094d\u0930 \u0928 \u0905\u092a\u0932\u094b\u0921 \u0915\u0930\u0947\u0902\u0964"},
gyR(){return"\u0915\u094b\u0908 \u091a\u093f\u0915\u093f\u0924\u094d\u0938\u0940\u092f \u0935\u0948\u0927\u0924\u093e \u0928\u0939\u0940\u0902"},
x7(a){return"\u091b\u093e\u0924\u094d\u0930: "+a},
